bool _rezkaMergeControlAdvanced(
  AdminApparatusQueueOrderActionControl? before,
  AdminApparatusQueueOrderActionControl? after,
) {
  if (before == null || after == null || !after.contractValid) return false;
  if (after.rezkaInputLineage.length <= before.rezkaInputLineage.length) {
    return false;
  }

  String activeInput(AdminApparatusQueueOrderActionControl control) {
    for (final link in control.rezkaInputLineage) {
      if (link.inUse) return link.inputBatchId;
    }
    return '';
  }

  final beforeActive = activeInput(before);
  final afterActive = activeInput(after);
  if (beforeActive.isEmpty ||
      afterActive.isEmpty ||
      beforeActive == afterActive) {
    return false;
  }
  final afterLinks = {
    for (final link in after.rezkaInputLineage) link.inputBatchId: link,
  };
  return before.rezkaInputLineage
          .every((link) => afterLinks.containsKey(link.inputBatchId)) &&
      afterLinks[beforeActive]?.status == 'processed' &&
      afterLinks[afterActive]?.inUse == true;
}

